/**
 * Copies the SQL migrations generated by drizzle-kit (./drizzle) into a
 * TypeScript module, so the app can apply them on start-up on any platform
 * (including serverless functions that can't read project files at runtime).
 *
 * Run automatically by `npm run db:generate`.
 */
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";

const root = path.resolve(__dirname, "..");
const folder = path.join(root, "drizzle");
const journal = JSON.parse(readFileSync(path.join(folder, "meta", "_journal.json"), "utf8")) as {
  entries: { tag: string; when: number; breakpoints: boolean }[];
};

const migrations = journal.entries.map((entry) => {
  const query = readFileSync(path.join(folder, `${entry.tag}.sql`), "utf8");
  return {
    tag: entry.tag,
    when: entry.when,
    // Same hash drizzle-orm's migrator uses, so drizzle-kit sees these as applied.
    hash: createHash("sha256").update(query).digest("hex"),
    statements: query
      .split("--> statement-breakpoint")
      .map((s) => s.trim())
      .filter(Boolean),
  };
});

const out = `// AUTO-GENERATED by scripts/embed-migrations.ts — do not edit by hand.
// Regenerate with: npm run db:generate

export type EmbeddedMigration = {
  tag: string;
  when: number;
  hash: string;
  statements: string[];
};

export const MIGRATIONS: EmbeddedMigration[] = ${JSON.stringify(migrations, null, 2)};
`;

writeFileSync(path.join(root, "src", "lib", "db", "migrations.generated.ts"), out);
console.log(`Embedded ${migrations.length} migration(s) into src/lib/db/migrations.generated.ts`);
